#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int n;        cin >> n;         vector<int> a(n);        for (int i = 0; i < n; i++) cin >> a[i];         unordered_map<int,int> freq;        int maxFreq = 0;         for (int x : a) {            freq[x]++;            maxFreq = max(maxFreq, freq[x]);        }         int distinct = freq.size();         if (distinct == 1) {            // all elements equal → always good            cout << "Yes\n";        }        else if (distinct == 2 && maxFreq <= (n + 1) / 2) {            cout << "Yes\n";        }        else {            cout << "No\n";        }    }     return 0;}